function t13Headers() {
  return {'User-Agent':'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36',
    'Referer':'https://m.ting13.cc/'};
}
function t13Url(value) {
  var u = String(value || '').replace(/&amp;/g, '&');
  if (/^https?:\/\/m\.ting13\.cc(?:\/|$)/i.test(u)) return u.replace(/^http:/, 'https:');
  if (u.charAt(0) === '/' && u.charAt(1) !== '/') return 'https://m.ting13.cc' + u;
  throw new Error('13听书网返回了无效的站内地址');
}
function t13Request(address, method, body, extra) {
  var u = t13Url(address);
  // 旧规则使用的简写 UA 无法稳定通过网站会话校验；切换后只重置验证 Cookie。
  if (source.get('t13SessionVersion') !== 'mobile-1') {
    cookie.removeCookie(u, '__51guid__');
    cookie.removeCookie(u, '__51refresh__guid');
    source.put('t13SessionVersion', 'mobile-1');
  }
  var limitedRetries = 0;
  for (var attempt = 0; attempt < 5; attempt++) {
    var headers = t13Headers();
    if (extra) Object.keys(extra).forEach(function(k) { headers[k] = extra[k]; });
    var requestUrl = u.split('#')[0] + (attempt > 0 ? '#source-session-' + attempt : '');
    var response = method === 'POST' ? java.post(requestUrl, body, headers) : java.connect(requestUrl, headers);
    var status = response.code();
    if (status >= 300 && status < 400) {
      var location = response.header('Location');
      if (!location) throw new Error('网站跳转缺少地址');
      u = t13Url(location);
      if (status === 303 || ((status === 301 || status === 302) && method === 'POST')) {
        method = 'GET';
        body = null;
      }
      continue;
    }
    if (status === 429) {
      if (limitedRetries++ >= 1) throw new Error('网站请求限流，请稍后重试');
      continue;
    }
    var html = response.body();
    var encoded = /var\s+reversed\s*=\s*"([A-Za-z0-9+/=]+)"/.exec(html);
    if (encoded && html.indexOf('Loading...') >= 0) {
      var code = java.base64DecodeToString(encoded[1].split('').reverse().join(''));
      var token = /var\s+token\s*=\s*'([^']+)'/.exec(code);
      if (!token || code.indexOf('__51guid__=') < 0) throw new Error('网站会话格式已变化');
      // 只提取会话值，不执行网站下发的 JavaScript。
      cookie.setCookie(u, '__51guid__=' + encodeURIComponent(token[1]) + '; __51refresh__guid=1');
      continue;
    }
    if (response.code() === 403 && html.length < 512 && html.indexOf('window.location.href') >= 0) continue;
    if (!response.isSuccessful()) throw new Error('13听书网 HTTP ' + response.code());
    return html;
  }
  throw new Error('13听书网会话初始化失败，请稍后重试');
}
function t13Header(address) {
  var path = String(address || '').split('#')[0];
  if (/^https:\/\/m\.ting13\.cc\/tingdirs\//.test(path)) t13Request(path, 'GET');
  return JSON.stringify(t13Headers());
}
function t13Search(word, pageNumber) {
  t13Request('/novelsearch/search/result.html', 'POST', 'searchword=' + encodeURIComponent(word));
  return 'https://m.ting13.cc/api/ajax/solist?word=' + encodeURIComponent(encodeURIComponent(word)) +
    '&type=name&page=' + pageNumber + '&order=1,' + JSON.stringify({headers:{
      Referer:'https://m.ting13.cc/novelsearch/search/result.html', 'X-Requested-With':'XMLHttpRequest'}});
}
function t13Toc(html) {
  var link = /href="(\/tingdirs\/[^"#]+)"/.exec(String(html));
  if (!link) throw new Error('未找到完整目录');
  return t13Url(link[1]);
}
function t13NextToc(html) {
  var match = /<li class="chapter-item js_chapter_item active">[\s\S]*?<\/li><li class="chapter-item js_chapter_item"><a href="([^"]+)"/.exec(String(html));
  if (!match) return '';
  return t13Url(match[1]) + ',{"retry":2}';
}
function t13Meta(html, name) {
  var match = new RegExp('<meta\\s+name="' + name + '"\\s*content="([^"]*)"', 'i').exec(html);
  if (!match || !match[1]) throw new Error('播放页缺少参数 ' + name);
  return match[1];
}
function t13Audio(html) {
  var pageHtml = String(html);
  var sc = t13Meta(pageHtml, '_c');
  var alphabet = 'PXhw7U1B0a9kQDKZsTjIASmOeNzxYG4CHo1JyRfg2b8FLpEvr3FtVnlqMidu6c';
  var sp = '';
  for (var i = 0; i < sc.length; i++) {
    var index = alphabet.indexOf(sc.charAt(i));
    sp += alphabet.charAt(Math.floor(Math.random() * 62)) +
      (index < 0 ? sc.charAt(i) : alphabet.charAt((index + 3) % 62)) +
      alphabet.charAt(Math.floor(Math.random() * 62));
  }
  var body = 'nid=' + encodeURIComponent(t13Meta(pageHtml, '_b')) +
    '&cid=' + encodeURIComponent(t13Meta(pageHtml, '_p')) + '&sort=' + encodeURIComponent(t13Meta(pageHtml, '_d'));
  var response = JSON.parse(t13Request('/api/mapi/play', 'POST', body,
    {sc:sc, sp:sp, 'X-Requested-With':'XMLHttpRequest'}));
  if (response.status !== 200 || !/^https?:\/\//i.test(response.url || '')) {
    throw new Error(response.msg || '播放接口未返回音频');
  }
  // 此音频域名已验证支持 HTTPS；其他域名保留网站返回的协议。
  return response.url.replace(/^http:\/\/mp3tt\.ysxs\.top\//i, 'https://mp3tt.ysxs.top/');
}
